import{_ as s}from"./chunks/folders.9ioZn9MV.js";import{_ as r,c as i,o,a2 as a}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse(`{"title":"Comparer des dossiers","description":"Visualisez les fichiers nouveaux, modifiés et manquants entre deux dossiers, filtrez l'arborescence et resynchronisez les deux côtés.","frontmatter":{"title":"Comparer des dossiers","description":"Visualisez les fichiers nouveaux, modifiés et manquants entre deux dossiers, filtrez l'arborescence et resynchronisez les deux côtés."},"headers":[],"relativePath":"fr/guide/folders.md","filePath":"fr/guide/folders.md","lastUpdated":1794296122000}`),t={name:"fr/guide/folders.md"};function n(u,e,l,d,c,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="comparer-des-dossiers" tabindex="-1">Comparer des dossiers <a class="header-anchor" href="#comparer-des-dossiers" aria-label="Permalink to &quot;Comparer des dossiers&quot;">​</a></h1><p>Quand deux dossiers devraient correspondre — une copie de travail et sa sauvegarde, un ancien export et un nouveau — les comparer fichier par fichier est fastidieux. qDiff affiche toute l&#39;arborescence d&#39;un seul coup.</p><img src="'+s+'" alt="Deux arborescences de dossiers avec des états de fichiers en couleur" class="guide-shot"><h2 id="ouvrir-deux-dossiers" tabindex="-1">Ouvrir deux dossiers <a class="header-anchor" href="#ouvrir-deux-dossiers" aria-label="Permalink to &quot;Ouvrir deux dossiers&quot;">​</a></h2><p>Déposez deux dossiers sur la fenêtre, ou choisissez-les depuis <strong>Fichier → Ouvrir</strong>. Les dossiers contenus dans les dossiers sont comparés eux aussi, pour vous donner une vue complète.</p><h2 id="lire-l-arborescence-d-un-coup-d-œil" tabindex="-1">Lire l&#39;arborescence d&#39;un coup d&#39;œil <a class="header-anchor" href="#lire-l-arborescence-d-un-coup-d-œil" aria-label="Permalink to &quot;Lire l&#39;arborescence d&#39;un coup d&#39;œil&quot;">​</a></h2><ul><li><strong>Vert</strong> — un fichier qui n&#39;existe que d&#39;un seul côté.</li><li><strong>Orange</strong> — le nom correspond mais le contenu diffère.</li><li><strong>Rouge</strong> — un fichier absent de l&#39;autre côté.</li><li><strong>Gris</strong> — les deux côtés correspondent.</li></ul><h2 id="n-afficher-que-l-essentiel" tabindex="-1">N&#39;afficher que l&#39;essentiel <a class="header-anchor" href="#n-afficher-que-l-essentiel" aria-label="Permalink to &quot;N&#39;afficher que l&#39;essentiel&quot;">​</a></h2><p>Utilisez les filtres par état pour masquer tout ce qui correspond déjà, ou saisissez une partie d&#39;un nom pour réduire la liste. Vous pouvez choisir une vérification rapide sur les noms seuls ou demander à qDiff de lire aussi le contenu — pratique lorsqu&#39;une sauvegarde semble correcte mais pourrait être périmée à l&#39;intérieur.</p><p>Même les grands dossiers s&#39;ouvrent vite : nul besoin de rester devant une barre de progression.</p><h2 id="remettre-les-choses-en-ordre-depuis-la-liste" tabindex="-1">Remettre les choses en ordre depuis la liste <a class="header-anchor" href="#remettre-les-choses-en-ordre-depuis-la-liste" aria-label="Permalink to &quot;Remettre les choses en ordre depuis la liste&quot;">​</a></h2><p>Copiez un fichier de l&#39;autre côté, supprimez un reliquat ou synchronisez tout un groupe — le tout depuis la même arborescence. Inutile de revenir au Finder.</p><div class="tip custom-block"><p class="custom-block-title">Explorez sans risque</p><p>Rien n&#39;est modifié sur le disque tant que vous ne lancez pas une action. Parcourir et filtrer une comparaison est totalement sans danger.</p></div><p>Ensuite : <a href="./projects.html">relisez un projet avant de valider</a>.</p>',14)])])}const q=r(t,[["render",n]]);export{h as __pageData,q as default};
